1: import { Injectable, computed, signal } from '@angular/core';
2: import type {
3:   EvaluacionProveedor,
4:   MaterialProveedor,
5:   Proveedor,
6: } from '../modelos/proveedor';
7: import {
8:   EVALUACIONES_SIMULADAS,
9:   PROVEEDORES_SIMULADOS,
10: } from '../datos-simulados/proveedores';
11: 
12: export type ResultadoEliminacion = 'eliminado' | 'desactivado' | 'no-encontrado';
13: 
14: /**
15:  * Estado en memoria del padrón de proveedores.
16:  *
17:  * La interfaz pública (listar, obtener, guardar, eliminar, evaluación) está
18:  * pensada para sustituirse por HttpClient contra:
19:  *   GET, POST, PATCH y DELETE /proveedores
20:  *   GET, POST, PATCH y DELETE /proveedores/{id}/materiales
21:  *   GET /proveedores/evaluacion
22:  * Nada de lo que ocurre aquí persiste en servidor.
23:  */
24: @Injectable({
25:   providedIn: 'root',
26: })
27: export class ProveedoresServicio {
28:   private readonly lista = signal<Proveedor[]>(structuredClone(PROVEEDORES_SIMULADOS));
29:   private readonly evaluaciones = signal<EvaluacionProveedor[]>(
30:     structuredClone(EVALUACIONES_SIMULADAS),
31:   );
32: 
33:   readonly proveedores = this.lista.asReadonly();
34:   readonly evaluacionesRegistradas = this.evaluaciones.asReadonly();
35: 
36:   /** Líneas activas de proveedores activos/en revisión, agrupadas por material. */
37:   readonly cobertura = computed<Map<number, MaterialProveedor[]>>(() => {
38:     const agrupado = new Map<number, MaterialProveedor[]>();
39: 
40:     for (const proveedor of this.lista()) {
41:       if (proveedor.estatus === 'INACTIVO') {
42:         continue;
43:       }
44:       for (const material of proveedor.materiales) {
45:         if (!material.activo) {
46:           continue;
47:         }
48:         const lineas = agrupado.get(material.materialId) ?? [];
49:         lineas.push(material);
50:         agrupado.set(material.materialId, lineas);
51:       }
52:     }
53: 
54:     return agrupado;
55:   });
56: 
57:   obtenerPorId(id: number): Proveedor | undefined {
58:     return this.lista().find((proveedor) => proveedor.id === id);
59:   }
60: 
61:   obtenerEvaluacion(id: number): EvaluacionProveedor | undefined {
62:     return this.evaluaciones().find((evaluacion) => evaluacion.proveedorId === id);
63:   }
64: 
65:   guardarProveedor(datos: Proveedor): void {
66:     const proveedor = structuredClone(datos);
67: 
68:     if (proveedor.id === 0) {
69:       proveedor.id = this.siguienteId();
70:       this.lista.update((actuales) => [...actuales, proveedor]);
71:       return;
72:     }
73: 
74:     this.lista.update((actuales) =>
75:       actuales.map((actual) => (actual.id === proveedor.id ? proveedor : actual)),
76:     );
77:   }
78: 
79:   /**
80:    * Regla del documento: solo se elimina si no hay órdenes de compra.
81:    * Con historial se desactiva, nunca se borra.
82:    */
83:   eliminarProveedor(id: number): ResultadoEliminacion {
84:     const proveedor = this.obtenerPorId(id);
85:     if (!proveedor) {
86:       return 'no-encontrado';
87:     }
88: 
89:     if (proveedor.tieneOrdenesCompra) {
90:       this.lista.update((actuales) =>
91:         actuales.map((actual) =>
92:           actual.id === id ? { ...actual, estatus: 'INACTIVO' as const } : actual,
93:         ),
94:       );
95:       return 'desactivado';
96:     }
97: 
98:     this.lista.update((actuales) => actuales.filter((actual) => actual.id !== id));
99:     this.evaluaciones.update((actuales) =>
100:       actuales.filter((evaluacion) => evaluacion.proveedorId !== id),
101:     );
102:     return 'eliminado';
103:   }
104: 
105:   reemplazarMateriales(proveedorId: number, materiales: MaterialProveedor[]): void {
106:     const copia = structuredClone(materiales);
107:     this.lista.update((actuales) =>
108:       actuales.map((actual) =>
109:         actual.id === proveedorId ? { ...actual, materiales: copia } : actual,
110:       ),
111:     );
112:   }
113: 
114:   private siguienteId(): number {
115:     return this.lista().reduce((maximo, proveedor) => Math.max(maximo, proveedor.id), 0) + 1;
116:   }
117: }

