1: import type { AbstractControl, ValidationErrors, ValidatorFn } from '@angular/forms';
2: 
3: /**
4:  * Validadores de presentación reutilizables (§10.3b del documento UNIQUE v3.0).
5:  * Solo validan la forma: la validación autoritativa corresponde a Flask.
6:  */
7: 
8: /** RFC de persona moral (12 caracteres) o física (13), con estructura oficial básica. */
9: export const rfcValido: ValidatorFn = (control: AbstractControl): ValidationErrors | null => {
10:   const valor = control.value;
11:   if (typeof valor !== 'string' || valor.trim() === '') {
12:     return null; // El RFC es opcional en el padrón; si se pide, se marcará required aparte.
13:   }
14: 
15:   const rfc = valor.trim().toUpperCase();
16:   const estructura = /^([A-ZÑ&]{3,4})(\d{2})(0[1-9]|1[0-2])(0[1-9]|[12]\d|3[01])([A-Z\d]{3})$/;
17: 
18:   return estructura.test(rfc) ? null : { rfc: true };
19: };
20: 
21: /** Exactamente 10 dígitos; se ignoran espacios y guiones. */
22: export const telefono10: ValidatorFn = (control: AbstractControl): ValidationErrors | null => {
23:   const valor = control.value;
24:   if (typeof valor !== 'string' || valor.trim() === '') {
25:     return null; // La presencia se valida con required.
26:   }
27: 
28:   const digitos = valor.replace(/\D/g, '');
29:   return digitos.length === 10 ? null : { telefono10: true };
30: };

