validarDescuento(descuento, ctx: {subtotal, cantidadArticulos, esPrimeraCompra, fecha?}): ValidacionDescuento {
 if (!descuento.activo) return ...
 const hoy = hoyIso();
 if (descuento.vigenteDesde > hoy) ...
 if (descuento.vigenteHasta && descuento.vigenteHasta < hoy) ...
 if (descuento.usosMaximos !== null && descuento.usosActuales >= descuento.usosMaximos) ...
 if (descuento.soloPrimeraCompra && !ctx.esPrimeraCompra) ...
 if (descuento.montoMinimo !== null && ctx.subtotal < descuento.montoMinimo) ...
 if (descuento.minArticulos !== null && ctx.cantidadArticulos < descuento.minArticulos) ...
 const monto = descuento.tipo==='PORCENTAJE' ? ctx.subtotal*descuento.valor/100 : Math.min(descuento.valor, ctx.subtotal);
 return {valido:true, motivo:'', monto:Math.round(monto*100)/100};
}
```
