import type { CosteoReceta, LineaReceta, MaterialCatalogo, Receta } from '../modelos/receta';

/** Parámetros de §11.5 del documento; IVA y margen objetivo son datos del sistema. */
export const IVA_PCT = 16;
export const MARGEN_OBJETIVO_PCT = 55;

/** Factores de conversión de la unidad de captura a la unidad base. */
const FACTORES_BASE: Record<LineaReceta['unidadCaptura'], number> = {
  cm2: 0.0001,
  cm: 0.01,
  m2: 1,
  m: 1,
  g: 1,
  pieza: 1,
};

export function convertirABase(valor: number, unidad: LineaReceta['unidadCaptura']): number {
  return Math.round(valor * FACTORES_BASE[unidad] * 1e6) / 1e6;
}

export function convertirDeBase(valor: number, unidad: LineaReceta['unidadCaptura']): number {
  const factor = FACTORES_BASE[unidad];
  return factor === 0 ? 0 : Math.round((valor / factor) * 1e6) / 1e6;
}

/** Fórmula de §7.5: neta × factor ÷ (1 − merma/100). */
export function cantidadBruta(cantidadNeta: number, factor: number, mermaPct: number): number {
  if (mermaPct >= 100) {
    return 0;
  }
  return Math.round((cantidadNeta * factor) / (1 - mermaPct / 100) * 1e4) / 1e4;
}

export function redondear(valor: number, decimales = 2): number {
  const factor = 10 ** decimales;
  return Math.round(valor * factor) / factor;
}

/**
 * Costeo de §7.5. El empaque se toma de las reglas POR_PRENDA del catálogo de
 * materiales (M15); el resto se captura en la propia receta.
 */
export function costear(
  receta: Receta,
  materiales: MaterialCatalogo[],
  empaquePorPrenda: number,
): CosteoReceta {
  const porCodigo = new Map(materiales.map((material) => [material.codigo, material]));
  const materiaPrima = receta.lineas.reduce((suma, linea) => {
    const material = porCodigo.get(linea.materialCodigo);
    return material ? suma + linea.cantidadBruta * material.costoBase : suma;
  }, 0);

  const costoEstandar =
    materiaPrima + empaquePorPrenda + receta.manoObra + receta.costoBordado + receta.costosIndirectos;
  const precioSugerido =
    costoEstandar / (1 - MARGEN_OBJETIVO_PCT / 100) * (1 + IVA_PCT / 100);

  return {
    materiaPrima: redondear(materiaPrima),
    empaque: redondear(empaquePorPrenda),
    manoObra: redondear(receta.manoObra),
    bordado: redondear(receta.costoBordado),
    indirectos: redondear(receta.costosIndirectos),
    costoEstandar: redondear(costoEstandar),
    precioSugerido: redondear(precioSugerido),
    margenObjetivo: MARGEN_OBJETIVO_PCT,
  };
}

/** Margen real = (precio / 1.16 − costo) ÷ (precio / 1.16). */
export function margenReal(precio: number, costo: number): number | null {
  if (precio <= 0) {
    return null;
  }
  const base = precio / (1 + IVA_PCT / 100);
  return redondear(((base - costo) / base) * 100, 1);
}

/**
 * "Alcanza para N prendas": el material con menor cobertura limita el cálculo.
 * El inventario es una lectura de demostración de M15.
 */
export function prendasPosibles(
  receta: Receta,
  inventario: Record<string, number>,
): number | null {
  const coberturas = receta.lineas
    .filter((linea) => linea.cantidadBruta > 0)
    .map((linea) => Math.floor((inventario[linea.materialCodigo] ?? 0) / linea.cantidadBruta));
  return coberturas.length === 0 ? null : Math.min(...coberturas);
}

import type { CodigoTalla } from '../../productos/modelos/producto-maestro';

/**
 * Modelos de interfaz de M11 · Recetas y bordados.
 * Corresponden a las entidades del §6; la persistencia y el cálculo
 * autoritativo corresponderán a Flask cuando se integre el backend.
 */

export type CategoriaMaterial =
  | 'Tela'
  | 'Hilo'
  | 'Estabilizador'
  | 'Avio'
  | 'Etiqueta'
  | 'Empaque';

export type UnidadBase = 'm2' | 'm' | 'g' | 'pieza';
export type UnidadCaptura = 'cm2' | 'cm' | 'm2' | 'm' | 'g' | 'pieza';
export type EstadoReceta = 'BORRADOR' | 'VIGENTE' | 'ARCHIVADA';
export type EstadoDiseno = 'PENDIENTE' | 'DIGITALIZADO';

export interface MaterialCatalogo {
  id: number;
  codigo: string;
  nombre: string;
  categoria: CategoriaMaterial;
  unidadBase: UnidadBase;
  costoBase: number;
  /** Merma precargada del material; el editor permite ajustarla por línea. */
  mermaPct: number;
  conColor: boolean;
  presentacion: string;
  /** Regla POR_PRENDA: se suma al empaque de cada prenda. */
  porPrenda: boolean;
}

export interface LineaReceta {
  id: number;
  materialCodigo: string;
  /** Cantidad neta convertida ya a la unidad base del material. */
  cantidadNeta: number;
  unidadCaptura: UnidadCaptura;
  factorConsumo: number;
  mermaPct: number;
  /** Derivada: neta × factor ÷ (1 − merma/100). */
  cantidadBruta: number;
  esEtiqueta: boolean;
  nota: string;
}

export interface BordadoReceta {
  id: number;
  disenoId: number;
  aplicaciones: number;
  ubicacion: string;
}

export interface EntradaBitacoraReceta {
  id: number;
  fecha: string;
  usuario: string;
  accion: string;
  detalle: string;
}

export interface Receta {
  id: number;
  productoId: number;
  talla: CodigoTalla;
  version: number;
  estado: EstadoReceta;
  origenRecetaId: number | null;
  manoObra: number;
  costoBordado: number;
  costosIndirectos: number;
  nota: string;
  creadaPor: string;
  creadaEn: string;
  activadaEn: string | null;
  lineas: LineaReceta[];
  bordados: BordadoReceta[];
  bitacora: EntradaBitacoraReceta[];
}

export interface HiloDiseno {
  id: number;
  materialCodigo: string;
  metrosPorAplicacion: number;
}

export interface DisenoBordado {
  id: number;
  codigo: string;
  nombre: string;
  anchoCm: number;
  altoCm: number;
  estado: EstadoDiseno;
  notas: string;
  activo: boolean;
  hilos: HiloDiseno[];
}

export interface CosteoReceta {
  materiaPrima: number;
  empaque: number;
  manoObra: number;
  bordado: number;
  indirectos: number;
  costoEstandar: number;
  precioSugerido: number;
  margenObjetivo: number;
}

/** Datos editables del editor de receta (sin identificadores generados). */
export interface DatosReceta {
  productoId: number;
  talla: CodigoTalla;
  nota: string;
  manoObra: number;
  costoBordado: number;
  costosIndirectos: number;
  lineas: Array<{
    materialCodigo: string;
    cantidadNeta: number;
    unidadCaptura: UnidadCaptura;
    factorConsumo: number;
    mermaPct: number;
    esEtiqueta: boolean;
    nota: string;
  }>;
  bordados: Array<{ disenoId: number; aplicaciones: number; ubicacion: string }>;
}

export interface DatosDiseno {
  nombre: string;
  anchoCm: number;
  altoCm: number;
  notas: string;
  activo: boolean;
  hilos: Array<{ materialCodigo: string; metrosPorAplicacion: number }>;
}

export interface ResultadoM11 {
  ok: boolean;
  mensaje: string;
  recetaId?: number;
  disenoId?: number;
}

export interface FilaHistorial {
  id: number;
  clave: string;
  descripcion: string;
  detalleA: string;
  detalleB: string;
  estado: 'IGUAL' | 'CAMBIO' | 'NUEVA' | 'ELIMINADA';
