.tabla tbody tr:nth-child(even) { background-color: var(--color-unique-fila); }

.celda-principal,
.celda-secundaria { display: block; }
.celda-principal { font-weight: 600; }

.celda-secundaria {
  color: var(--color-unique-texto-suave);
  font-size: 0.72rem;
  line-height: 1.35;
}

.chip {
  display: inline-block;
  padding: 0.25rem 0.6rem;
  border-radius: 999px;
  font-family: var(--font-interfaz);
  font-size: 0.7rem;
  font-weight: 700;
  letter-spacing: 0.04em;
}

.chip--vigente { background-color: var(--color-unique-exito-suave); color: #217a47; }
.chip--borrador { background-color: var(--color-unique-adv-suave); color: #7a5606; }
.chip--archivada { background-color: var(--color-unique-fila); color: var(--color-unique-texto-suave); }

.acciones {
  display: flex;
  flex-wrap: wrap;
  gap: 0.3rem 0.7rem;
  min-width: 12rem;
}

.accion {
  padding: 0;
  border: 0;
  background: transparent;
  color: var(--color-unique-ciruela);
  font-family: var(--font-interfaz);
  font-size: 0.78rem;
  font-weight: 600;
  text-decoration: underline;
  text-underline-offset: 3px;
  cursor: pointer;
}

.accion:hover { color: var(--color-unique-morado); }
.accion--peligro { color: #a52b3c; }

.estado {
  padding: 2rem 1rem;
  border: 1px dashed var(--color-unique-orquidea);
  border-radius: 16px;
  background-color: var(--color-unique-fila);
  text-align: center;
}

.estado strong { color: var(--color-unique-morado); }
.estado p { margin: 0.4rem 0 0; color: var(--color-unique-texto-suave); font-size: 0.85rem; }

.nota {
  margin: 1.25rem 0 0;
  padding: 0.85rem 1rem;
  border-radius: 12px;
