393:       ok: true,
394:       mensaje: 'Versión activada en memoria. La anterior pasó a ARCHIVADA; M10 ya consulta el nuevo costo.',
395:     };
396:   }
397: 
398:   archivarReceta(id: number): ResultadoM11 {
399:     const receta = this.recetaDe(id);
400:     if (!receta || receta.estado === 'ARCHIVADA') {
401:       return { ok: false, mensaje: 'La receta ya está archivada o no existe.' };
402:     }
403:     const ahora = new Date().toISOString();
404:     this.lista.update((recetas) =>
405:       recetas.map((item) =>
406:         item.id === id
407:           ? {
408:               ...item,
409:               estado: 'ARCHIVADA' as const,
410:               bitacora: [
411:                 ...item.bitacora,
412:                 {
413:                   id: item.bitacora.length + 1,
414:                   fecha: ahora,
415:                   usuario: 'Administrador',
416:                   accion: 'Archivado',
417:                   detalle: `Versión ${item.version} archivada manualmente.`,
418:                 },
419:               ],
420:             }
421:           : item,
422:       ),
423:     );
424:     return {
425:       ok: true,
426:       mensaje: 'Receta archivada. Si era vigente, el producto dejará de cumplir la regla de activación en M10.',
427:     };
428:   }
429: 
430:   comparar(idA: number, idB: number): FilaHistorial[] {
431:     const a = this.recetaDe(idA);
432:     const b = this.recetaDe(idB);
433:     if (!a || !b) {
434:       return [];
435:     }
436: 
437:     const filas: FilaHistorial[] = [];
438:     const claves = new Set([...a.lineas.map((l) => l.materialCodigo), ...b.lineas.map((l) => l.materialCodigo)]);
439:     for (const clave of claves) {
440:       const lineaA = a.lineas.find((linea) => linea.materialCodigo === clave);
441:       const lineaB = b.lineas.find((linea) => linea.materialCodigo === clave);
442:       const detalle = (linea: LineaReceta | undefined): string =>
443:         linea
444:           ? `${linea.cantidadNeta} ${linea.unidadCaptura} · factor ${linea.factorConsumo} · merma ${linea.mermaPct} % · bruta ${linea.cantidadBruta}`
445:           : '—';
446:       filas.push({
447:         id: filas.length + 1,
448:         clave,
449:         descripcion: this.nombreMaterial(clave),
450:         detalleA: detalle(lineaA),
451:         detalleB: detalle(lineaB),
452:         estado:
453:           !lineaA ? 'NUEVA' : !lineaB ? 'ELIMINADA' : detalle(lineaA) === detalle(lineaB) ? 'IGUAL' : 'CAMBIO',
454:       });
455:     }
456: 
457:     filas.push(
458:       {
459:         id: filas.length + 1,
460:         clave: 'COSTOS',
461:         descripcion: 'Mano de obra / bordado / indirectos',
462:         detalleA: `${a.manoObra} / ${a.costoBordado} / ${a.costosIndirectos}`,
463:         detalleB: `${b.manoObra} / ${b.costoBordado} / ${b.costosIndirectos}`,
464:         estado:
465:           a.manoObra === b.manoObra &&
466:           a.costoBordado === b.costoBordado &&
467:           a.costosIndirectos === b.costosIndirectos
468:             ? 'IGUAL'
469:             : 'CAMBIO',
470:       },
471:       {
472:         id: filas.length + 1,
473:         clave: 'BORDADOS',
474:         descripcion: 'Diseños de bordado enlazados',
475:         detalleA: a.bordados.map((bordado) => `${this.nombreDiseno(bordado.disenoId)} ×${bordado.aplicaciones}`).join('; ') || '—',
476:         detalleB: b.bordados.map((bordado) => `${this.nombreDiseno(bordado.disenoId)} ×${bordado.aplicaciones}`).join('; ') || '—',
477:         estado:
478:           a.bordados.length === b.bordados.length &&
479:           a.bordados.every((bordado, indice) =>
480:             bordado.disenoId === b.bordados[indice]?.disenoId &&
481:             bordado.aplicaciones === b.bordados[indice]?.aplicaciones)
482:             ? 'IGUAL'
483:             : 'CAMBIO',
484:       },
485:     );
486:     return filas;
487:   }
488: 
489:   guardarDiseno(datos: DatosDiseno, id?: number): ResultadoM11 {
490:     const actual = id === undefined ? undefined : this.disenoDe(id);
491:     if (id !== undefined && !actual) {
492:       return { ok: false, mensaje: 'No encontramos el diseño.' };
493:     }
494:     const nombre = datos.nombre.trim();
495:     if (nombre.length < 3) {
496:       return { ok: false, mensaje: 'El nombre del diseño debe tener al menos 3 caracteres.' };
497:     }
498:     if (datos.anchoCm <= 0 || datos.altoCm <= 0) {
499:       return { ok: false, mensaje: 'El ancho y el alto deben ser mayores a cero.' };
500:     }
501:     if (datos.hilos.some((hilo) => hilo.metrosPorAplicacion < 0)) {
502:       return { ok: false, mensaje: 'Los metros por aplicación no pueden ser negativos.' };
503:     }
504: 
505:     const conHilos = datos.hilos.some((hilo) => hilo.metrosPorAplicacion > 0);
506:     const diseno: DisenoBordado = {
507:       id: actual?.id ?? this.siguienteDisenoId(),
508:       codigo: actual?.codigo ?? this.siguienteCodigoDiseno(),
509:       nombre,
510:       anchoCm: redondear(datos.anchoCm, 1),
511:       altoCm: redondear(datos.altoCm, 1),
512:       estado: actual?.estado === 'DIGITALIZADO' || conHilos ? 'DIGITALIZADO' : 'PENDIENTE',
513:       notas: datos.notas.trim(),
514:       activo: datos.activo,
515:       hilos: datos.hilos.map((hilo, indice) => ({
516:         id: actual?.hilos[indice]?.id ?? this.siguienteHiloId() + indice,
517:         materialCodigo: hilo.materialCodigo,
518:         metrosPorAplicacion: redondear(hilo.metrosPorAplicacion, 3),
519:       })),
520:     };
521: 
522:     this.disenosLista.update((disenos) =>
523:       actual
524:         ? disenos.map((item) => (item.id === diseno.id ? diseno : item))
525:         : [...disenos, diseno],
526:     );
527:     return {
528:       ok: true,
529:       disenoId: diseno.id,
530:       mensaje: actual
531:         ? 'Diseño actualizado en memoria.'
532:         : `Diseño ${diseno.codigo} creado en estado ${diseno.estado}. Consumo de hilo: ${diseno.hilos.reduce((s, h) => s + h.metrosPorAplicacion, 0)} m por aplicación.`,
533:     };
534:   }
535: 
536:   digitalizarDiseno(id: number): ResultadoM11 {
537:     const diseno = this.disenoDe(id);
538:     if (!diseno) {
539:       return { ok: false, mensaje: 'No encontramos el diseño.' };
540:     }
541:     if (diseno.hilos.length === 0 || diseno.hilos.every((hilo) => hilo.metrosPorAplicacion <= 0)) {
542:       return {
543:         ok: false,
544:         mensaje: 'Captura al menos un hilo con metros por aplicación antes de digitalizar.',
545:       };
546:     }
547:     this.disenosLista.update((disenos) =>
548:       disenos.map((item) => (item.id === id ? { ...item, estado: 'DIGITALIZADO' as const } : item)),
549:     );
550:     return {
551:       ok: true,
552:       mensaje: `${diseno.codigo} marcado como DIGITALIZADO. Las recetas que lo usan ya consideran el hilo en su costo.`,
553:     };
554:   }
555: 
556:   eliminarDiseno(id: number): ResultadoM11 {
557:     const diseno = this.disenoDe(id);
558:     if (!diseno) {
559:       return { ok: false, mensaje: 'No encontramos el diseño.' };
560:     }
561:     const usado = this.lista().some((receta) => receta.bordados.some((bordado) => bordado.disenoId === id));
562:     if (usado) {
563:       return {
564:         ok: false,
565:         mensaje: `${diseno.codigo} está enlazado a una receta. No se elimina para conservar el consumo de las órdenes.`,
566:       };
567:     }
568:     this.disenosLista.update((disenos) => disenos.filter((item) => item.id !== id));
569:     return { ok: true, mensaje: `${diseno.codigo} eliminado de la demostración.` };
570:   }
571: 
572:   etiquetasHilo(): MaterialCatalogo[] {
573:     return MATERIALES.filter((material) => material.codigo.startsWith('HIL-BOR-'));
574:   }
575: 
576:   private siguienteRecetaId(): number {
577:     return this.lista().reduce((maximo, receta) => Math.max(maximo, receta.id), 0) + 1;
578:   }
579: 
580:   private siguienteVersion(productoId: number, talla: CodigoTalla): number {
581:     return (
582:       this.recetasDeProducto(productoId, talla).reduce((maximo, receta) => Math.max(maximo, receta.version), 0) + 1
583:     );
584:   }
585: 
586:   private siguienteLineaId(): number {
587:     return (
588:       this.lista().reduce(
589:         (maximo, receta) => Math.max(maximo, ...receta.lineas.map((linea) => linea.id)),
590:         0,
591:       ) + 1
592:     );
593:   }
594: 
595:   private siguienteBordadoId(): number {
596:     return (
597:       this.lista().reduce(
598:         (maximo, receta) => Math.max(maximo, ...receta.bordados.map((bordado) => bordado.id)),
599:         0,
600:       ) + 1
601:     );
602:   }
603: 
604:   private siguienteDisenoId(): number {
605:     return this.disenosLista().reduce((maximo, diseno) => Math.max(maximo, diseno.id), 0) + 1;
606:   }
607: 
608:   private siguienteCodigoDiseno(): string {
609:     const usados = new Set(this.disenosLista().map((diseno) => diseno.codigo));
610:     let consecutivo = 1;
611:     while (usados.has(`DIS-${String(consecutivo).padStart(3, '0')}`)) {
612:       consecutivo += 1;
613:     }
614:     return `DIS-${String(consecutivo).padStart(3, '0')}`;
615:   }
616: 
617:   private siguienteHiloId(): number {
618:     return (
619:       this.disenosLista().reduce(
620:         (maximo, diseno) => Math.max(maximo, ...diseno.hilos.map((hilo) => hilo.id)),
621:         0,
622:       ) + 1
623:     );
624:   }
625: }

