20: const FACTOR_IVA = 1.16;
21: 
22: /**
23:  * Estado de M10 en memoria. Sustituir por HttpClient cuando Flask esté disponible.
24:  * Genera los SKU con la regla 6.5 y conserva las fronteras de propiedad: el costo
25:  * y la existencia se leen (demo), M11 y M12 son los dueños reales.
26:  */
27: @Injectable({
28:   providedIn: 'root',
29: })
30: export class ProductosServicio {
31:   private readonly lista = signal<ProductoMaestro[]>(
32:     structuredClone(PRODUCTOS_MAESTRO_SIMULADOS),
33:   );
34: 
35:   readonly productos = this.lista.asReadonly();
36:   readonly categorias = CATEGORIAS_PRODUCTO;
37:   readonly colores = COLORES_PRODUCTO;
38:   readonly tallas = TALLAS_PRODUCTO;
39: 
40:   readonly visibles = computed(() =>
41:     this.lista().filter((producto) => producto.activo && producto.eliminadoEn === null),
42:   );
43: 
44:   readonly filasVariantes = computed<FilaVariante[]>(() =>
45:     this.lista().flatMap((producto) =>
46:       producto.variantes.map((variante) => ({
47:         productoId: producto.id,
48:         productoNombre: producto.nombre,
49:         categoria: this.nombreCategoria(producto.categoriaId),
50:         variante,
51:       })),
52:     ),
53:   );
54: 
55:   readonly indicadores = computed(() => {
56:     const productos = this.lista();
57:     return {
58:       total: productos.length,
59:       activos: productos.filter((producto) => producto.activo && producto.eliminadoEn === null)
60:         .length,
61:       borradores: productos.filter((producto) => !producto.activo && producto.eliminadoEn === null)
62:         .length,
63:       variantes: productos.reduce((suma, producto) => suma + producto.variantes.length, 0),
64:     };
65:   });
