67:   obtenerProducto(id: number): ProductoMaestro | undefined {
68:     return this.lista().find((producto) => producto.id === id);
69:   }
70: 
71:   categoriaDe(id: number): CategoriaProducto | undefined {
72:     return this.categorias.find((categoria) => categoria.id === id);
73:   }
74: 
75:   nombreCategoria(id: number): string {
76:     return this.categoriaDe(id)?.nombre ?? 'Sin categoría';
77:   }
78: 
79:   nombreColor(codigo: CodigoColor): string {
80:     return this.colores.find((color) => color.codigo === codigo)?.nombre ?? codigo;
81:   }
82: 
83:   nombreTalla(codigo: CodigoTalla): string {
84:     return this.tallas.find((talla) => talla.codigo === codigo)?.nombre ?? codigo;
85:   }
