87:   /** Tallas permitidas por categoría; GO y BO usan únicamente UN. */
88:   tallasPorCategoria(id: number): CodigoTalla[] {
89:     const categoria = this.categoriaDe(id);
90:     if (!categoria || !categoria.usaTallas) {
91:       return ['UN'];
92:     }
93:     return this.tallas.filter((talla) => talla.codigo !== 'UN').map((talla) => talla.codigo);
94:   }
95: 
96:   /**
97:    * Código base del SKU. Se consideran también los productos desactivados o
98:    * dados de baja: si SD existe, el siguiente es SD2, después SD3 (§6.5).
99:    */
100:   siguienteCodigoSku(categoriaId: number, excluirId?: number): string {
101:     const categoria = this.categoriaDe(categoriaId);
102:     if (!categoria) {
103:       return '';
104:     }
105: 
106:     const usados = new Set(
107:       this.lista()
108:         .filter(
109:           (producto) => producto.categoriaId === categoriaId && producto.id !== excluirId,
110:         )
111:         .map((producto) => producto.codigoSku),
112:     );
113: 
114:     if (!usados.has(categoria.prefijo)) {
115:       return categoria.prefijo;
116:     }
117: 
118:     let consecutivo = 2;
119:     while (usados.has(`${categoria.prefijo}${consecutivo}`)) {
120:       consecutivo += 1;
121:     }
122:     return `${categoria.prefijo}${consecutivo}`;
123:   }
124: 
125:   /** Vista previa de los SKU que se generarían con la combinación indicada. */
126:   previsualizarSkus(codigo: string, tallas: CodigoTalla[], colores: CodigoColor[]): string[] {
127:     if (codigo === '' || tallas.length === 0 || colores.length === 0) {
128:       return [];
129:     }
130:     return tallas.flatMap((talla) => colores.map((color) => `${codigo}-${talla}-${color}`));
131:   }
132: 
133:   precioSinIva(precio: number): number {
134:     return Math.round((precio / FACTOR_IVA) * 100) / 100;
135:   }
136: 
137:   /** Margen real (%) según §7 de M11: (precio / 1.16 − costo) ÷ (precio / 1.16). */
138:   margenReal(precio: number, costo: number | null): number | null {
139:     if (costo === null || precio <= 0) {
140:       return null;
141:     }
142:     const base = precio / FACTOR_IVA;
143:     return Math.round(((base - costo) / base) * 1000) / 10;
144:   }
145: 
146:   /** Razones por las que un producto no puede activarse; vacío significa que sí puede. */
147:   validarActivacion(producto: ProductoMaestro): string[] {
148:     const razones: string[] = [];
149:     if (producto.imagenes.length === 0) {
150:       razones.push('Agrega al menos una imagen.');
151:     }
152:     const faltantes = producto.tallas.filter(
153:       (talla) => !producto.recetasVigentes.includes(talla),
154:     );
155:     if (faltantes.length > 0) {
156:       razones.push(
157:         `Falta receta VIGENTE (M11) para ${faltantes.map((talla) => this.nombreTalla(talla)).join(', ')}.`,
158:       );
159:     }
160:     return razones;
161:   }
162: 
163:   guardarProducto(datos: DatosProducto, id?: number): ResultadoProducto {
164:     const nombre = datos.nombre.trim();
165:     const categoria = this.categoriaDe(datos.categoriaId);
166:     const colores = this.colores
