168:       .filter((color) => datos.colores.includes(color));
169:     const tallas = this.tallasPorCategoria(datos.categoriaId).filter((talla) =>
170:       datos.tallas.includes(talla),
171:     );
172: 
173:     if (!categoria) {
174:       return { ok: false, mensaje: 'Selecciona una categoría válida.' };
175:     }
176:     if (nombre.length < 3) {
177:       return { ok: false, mensaje: 'El nombre del producto debe tener al menos 3 caracteres.' };
178:     }
179:     if (!Number.isFinite(datos.precioVenta) || datos.precioVenta <= 0) {
180:       return { ok: false, mensaje: 'El precio de venta debe ser mayor a cero.' };
181:     }
182:     if (colores.length === 0 || tallas.length === 0) {
183:       return { ok: false, mensaje: 'Selecciona al menos un color y una talla.' };
184:     }
185: 
186:     const actual = id === undefined ? undefined : this.obtenerProducto(id);
187:     if (id !== undefined && !actual) {
188:       return { ok: false, mensaje: 'No encontramos el producto que intentas editar.' };
189:     }
190: 
191:     const codigoSku = actual?.codigoSku ?? this.siguienteCodigoSku(datos.categoriaId);
192:     const imagenes = this.construirImagenes(datos.imagenGeneral, datos.imagenesPorColor, colores);
193:     const variantes = this.construirVariantes(
194:       actual?.variantes ?? [],
195:       codigoSku,
196:       tallas,
197:       colores,
198:       datos.stockMinimo,
199:       datos.cantidadReposicion,
200:     );
201:     const bitacora = [...(actual?.bitacora ?? [])];
202:     if (actual && actual.precioVenta !== datos.precioVenta) {
203:       bitacora.push({
204:         id: bitacora.reduce((maximo, entrada) => Math.max(maximo, entrada.id), 0) + 1,
205:         fecha: new Date().toISOString(),
206:         usuario: 'Administrador',
207:         campo: 'precio_venta',
208:         detalle: `De ${this.formatoMoneda(actual.precioVenta)} a ${this.formatoMoneda(datos.precioVenta)}. Las ventas anteriores no se modifican.`,
209:       });
210:     }
211: 
212:     const producto: ProductoMaestro = {
213:       id: actual?.id ?? this.siguienteProductoId(),
214:       slug: actual?.slug ?? this.slugUnico(nombre),
215:       nombre,
216:       codigoSku,
217:       categoriaId: datos.categoriaId,
218:       descripcion: datos.descripcion.trim(),
219:       composicionTextil: datos.composicionTextil.trim(),
220:       guiaMedidas: datos.guiaMedidas.trim(),
221:       precioVenta: datos.precioVenta,
222:       permiteBajoPedido: datos.permiteBajoPedido,
223:       activo: actual?.activo ?? false,
224:       eliminadoEn: actual?.eliminadoEn ?? null,
225:       imagenes,
226:       tallas,
227:       colores,
228:       variantes,
229:       costoEstandar: actual?.costoEstandar ?? null,
230:       recetasVigentes: actual?.recetasVigentes ?? [],
231:       tieneHistorial: actual?.tieneHistorial ?? false,
232:       bitacora,
233:     };
234: 
235:     this.lista.update((productos) =>
236:       actual
237:         ? productos.map((item) => (item.id === producto.id ? producto : item))
238:         : [...productos, producto],
239:     );
240: 
241:     return {
242:       ok: true,
243:       productoId: producto.id,
244:       mensaje: actual
245:         ? `Producto actualizado en memoria. ${variantes.length} variante(s), ningún SKU existente modificado.`
246:         : `Producto creado en memoria con ${variantes.length} variante(s) y SKU generados. Queda como borrador hasta integrar M11.`,
247:     };
248:   }
249: 
250:   cambiarActivo(id: number, activar: boolean): ResultadoProducto {
251:     const producto = this.obtenerProducto(id);
252:     if (!producto) {
253:       return { ok: false, mensaje: 'No encontramos el producto.' };
254:     }
255: 
256:     if (activar) {
257:       const razones = this.validarActivacion(producto);
258:       if (razones.length > 0) {
259:         return { ok: false, mensaje: `No se puede activar: ${razones.join(' ')}` };
260:       }
261:     }
262: 
263:     this.lista.update((productos) =>
264:       productos.map((item) => (item.id === id ? { ...item, activo: activar } : item)),
265:     );
266: 
267:     return {
268:       ok: true,
269:       mensaje: activar
270:         ? 'Producto marcado como activo en memoria. M03 lo publicará cuando Flask sincronice el catálogo.'
271:         : 'Producto desactivado en memoria; dejará de mostrarse en la tienda al integrar M03.',
272:     };
273:   }
274: 
275:   /** Desactiva o activa una sola variante, sin afectar a las demás. */
276:   alternarVariante(idProducto: number, idVariante: number): boolean {
277:     const producto = this.obtenerProducto(idProducto);
278:     if (!producto || !producto.variantes.some((variante) => variante.id === idVariante)) {
279:       return false;
280:     }
281: 
282:     this.lista.update((productos) =>
283:       productos.map((item) =>
284:         item.id === idProducto
285:           ? {
286:               ...item,
287:               variantes: item.variantes.map((variante) =>
288:                 variante.id === idVariante ? { ...variante, activa: !variante.activa } : variante,
289:               ),
290:             }
291:           : item,
292:       ),
293:     );
294:     return true;
295:   }
296: 
297:   eliminarProducto(id: number): ResultadoProducto {
298:     const producto = this.obtenerProducto(id);
299:     if (!producto) {
300:       return { ok: false, mensaje: 'No encontramos el producto.' };
301:     }
302: 
303:     if (producto.tieneHistorial) {
304:       this.lista.update((productos) =>
305:         productos.map((item) =>
306:           item.id === id
307:             ? { ...item, activo: false, eliminadoEn: new Date().toISOString() }
308:             : item,
309:         ),
310:       );
311:       return {
312:         ok: true,
313:         modo: 'desactivado',
314:         mensaje: 'Producto desactivado con borrado lógico: se conservan ventas, recetas y movimientos.',
315:       };
316:     }
317: 
318:     this.lista.update((productos) => productos.filter((item) => item.id !== id));
319:     return {
320:       ok: true,
321:       modo: 'eliminado',
322:       mensaje: 'Producto eliminado de la demostración al no tener ventas ni movimientos.',
323:     };
324:   }
325: 
326:   /** Proyección para M03: solo productos activos, sin costos. */
327:   productosActivosParaTienda(): IProducto[] {
328:     return this.visibles().map((producto) => ({
329:       id: producto.id,
330:       slug: producto.slug,
331:       nombre: producto.nombre,
332:       descripcion: producto.descripcion,
333:       descripcionDetalle: producto.descripcion,
334:       precio: producto.precioVenta,
335:       categoria: this.nombreCategoria(producto.categoriaId),
336:       imagen: producto.imagenes[0]?.url ?? '',
337:     }));
338:   }
339: 
340:   private construirImagenes(
341:     general: string,
342:     porColor: Partial<Record<CodigoColor, string>>,
343:     colores: CodigoColor[],
344:   ): ImagenProducto[] {
345:     const imagenes: ImagenProducto[] = [];
346:     if (general !== '') {
347:       imagenes.push({ color: null, url: general, orden: 1 });
348:     }
349:     colores.forEach((color, indice) => {
350:       const url = porColor[color];
351:       if (url) {
352:         imagenes.push({ color, url, orden: indice + 2 });
353:       }
354:     });
355:     return imagenes;
356:   }
357: 
358:   private construirVariantes(
359:     existentes: ProductoMaestro['variantes'],
360:     codigoSku: string,
361:     tallas: CodigoTalla[],
362:     colores: CodigoColor[],
363:     stockMinimo: number,
364:     cantidadReposicion: number,
365:   ): ProductoMaestro['variantes'] {
366:     const variantes = [...existentes];
367:     let siguienteId = this.siguienteVarianteId();
368: 
369:     for (const talla of tallas) {
370:       for (const color of colores) {
371:         const yaExiste = variantes.some(
372:           (variante) => variante.talla === talla && variante.color === color,
373:         );
374:         if (yaExiste) {
375:           continue;
376:         }
377:         variantes.push({
378:           id: siguienteId++,
379:           sku: `${codigoSku}-${talla}-${color}`,
380:           talla,
381:           color,
382:           activa: true,
383:           existencia: 0,
384:           reservado: 0,
385:           stockMinimo,
386:           cantidadReposicion,
387:         });
388:       }
389:     }
390:     return variantes;
391:   }
392: 
393:   private siguienteProductoId(): number {
394:     return this.lista().reduce((maximo, producto) => Math.max(maximo, producto.id), 0) + 1;
395:   }
396: 
397:   private siguienteVarianteId(): number {
398:     return (
399:       this.lista().reduce(
400:         (maximo, producto) =>
401:           Math.max(maximo, ...producto.variantes.map((variante) => variante.id)),
402:         0,
403:       ) + 1
404:     );
405:   }
406: 
407:   private slugUnico(nombre: string): string {
408:     const base =
409:       nombre
410:         .normalize('NFD')
411:         .replace(/[\u0300-\u036f]/g, '')
412:         .toLowerCase()
413:         .replace(/[^a-z0-9]+/g, '-')
414:         .replace(/^-|-$/g, '') || 'producto';
415:     const usados = new Set(this.lista().map((producto) => producto.slug));
416:     if (!usados.has(base)) {
417:       return base;
418:     }
419:     let consecutivo = 2;
420:     while (usados.has(`${base}-${consecutivo}`)) {
421:       consecutivo += 1;
422:     }
423:     return `${base}-${consecutivo}`;
424:   }
425: 
426:   private formatoMoneda(valor: number): string {
427:     return new Intl.NumberFormat('es-MX', {
428:       style: 'currency',
429:       currency: 'MXN',
430:     }).format(valor);
431:   }
432: }

