  margin: 0.4rem 0 0;
  color: var(--color-unique-texto-suave);
  font-size: 0.9rem;
  line-height: 1.5;
}

.bloque { padding: 1.25rem; margin-bottom: 1.25rem; }

.barra {
  display: grid;
  gap: 0.75rem;
  margin-bottom: 1rem;
}

.campo {
  display: flex;
  flex-direction: column;
  gap: 0.3rem;
  color: var(--color-unique-morado);
  font-family: var(--font-interfaz);
  font-size: 0.8125rem;
  font-weight: 600;
}

.campo__entrada {
  width: 100%;
  max-width: 22rem;
  min-height: 2.5rem;
  padding: 0.5rem 0.75rem;
  border: 1px solid #d9bfdb;
  border-radius: 12px;
  background-color: #ffffff;
  color: var(--color-unique-texto);
  font-family: var(--font-texto);
  font-size: 0.85rem;
}

.campo__entrada:focus {
  border-color: var(--color-unique-orquidea);
  outline: 0;
  box-shadow: 0 0 0 3px rgb(191 126 187 / 0.22);
}

.barra__nota {
  margin: 0;
  color: var(--color-unique-texto-suave);
  font-size: 0.76rem;
}

.tabla-contenedor { overflow-x: auto; }

.tabla {
  width: 100%;
  min-width: 72rem;
  border-collapse: collapse;
  font-size: 0.8rem;
}

.tabla--resumen { min-width: 42rem; }

.tabla th {
  padding: 0.65rem;
  background-color: var(--color-unique-ciruela);
  color: #ffffff;
  font-family: var(--font-interfaz);
  font-size: 0.72rem;
  text-align: left;
